// ===== PUBLIC GET REQUESTS =====
export const getRooms = async (filters = {}) => {
  let filtered = [...inMemoryRooms];

  if (filters.search || filters.searchQuery) {
    const q = (filters.search || filters.searchQuery).toLowerCase();
    filtered = filtered.filter(
      r =>
        (r.title && r.title.toLowerCase().includes(q)) ||
        (r.name && r.name.toLowerCase().includes(q)) ||
        (r.address && r.address.toLowerCase().includes(q)) ||
        (r.description && r.description.toLowerCase().includes(q))
    );
  }

  if (filters.roomType && filters.roomType !== 'all') {
    filtered = filtered.filter(r => r.roomType === filters.roomType);
  }

  if (filters.gender && filters.gender !== 'any') {
    filtered = filtered.filter(r => r.gender === filters.gender || r.gender === 'any');
  }

  if (filters.maxPrice && Number(filters.maxPrice) > 0) {
    const max = Number(filters.maxPrice);
    filtered = filtered.filter(r => (r.rent || r.price_per_month) <= max);
  }

  return filtered;
};

export const getMess = async (filters = {}) => {
  let filtered = [...inMemoryMess];

  if (filters.search || filters.searchQuery) {
    const q = (filters.search || filters.searchQuery).toLowerCase();
    filtered = filtered.filter(
      m =>
        (m.title && m.title.toLowerCase().includes(q)) ||
        (m.name && m.name.toLowerCase().includes(q)) ||
        (m.address && m.address.toLowerCase().includes(q)) ||
        (m.description && m.description.toLowerCase().includes(q))
    );
  }

  if (filters.messType && filters.messType !== 'all') {
    filtered = filtered.filter(m => m.messType === filters.messType || m.messType === 'both');
  }

  if (filters.maxPrice && Number(filters.maxPrice) > 0) {
    const max = Number(filters.maxPrice);
    filtered = filtered.filter(m => (m.price_per_month || m.pricing?.monthlyOneTime || 0) <= max);
  }

  return filtered;
};

export const getItemById = async (itemType, itemId) => {
  if (itemType === 'mess') {
    const item = inMemoryMess.find(m => m.mess_id === itemId || m.id === itemId);
    return item || inMemoryMess[0];
  } else {
    const item = inMemoryRooms.find(r => r.room_id === itemId || r.id === itemId);
    return item || inMemoryRooms[0];
  }
};

