export const createRoom = async (roomData) => {
  const newRoom = {
    ...roomData,
    room_id: `room-custom-${Date.now()}`,
    title: roomData.title || roomData.name,
    status: 'approved',
    created_at: new Date().toISOString(),
    rating: 5.0,
    cover_photo_url: roomData.cover_photo_url || MOCK_ROOMS[0].cover_photo_url,
    location: roomData.location || { lat: 21.1458, lng: 79.0882 }
  };
  inMemoryRooms.unshift(newRoom);
  return newRoom;
};

