export const createBooking = async (bookingData) => {
  const isMess = bookingData.itemType === 'mess';
  const newBooking = {
    booking_id: `bk-${Date.now()}`,
    ...bookingData,
    status: isMess ? 'confirmed' : 'pending',
    created_at: new Date().toISOString(),
    title: isMess
      ? (inMemoryMess.find(m => m.mess_id === bookingData.itemId)?.name || inMemoryMess.find(m => m.mess_id === bookingData.itemId)?.title || "Selected Mess")
      : (inMemoryRooms.find(r => r.room_id === bookingData.itemId)?.title || "Selected Room")
  };
  inMemoryStudentBookings.unshift(newBooking);
  return { success: true, booking: newBooking, message: isMess ? "Mess subscription confirmed!" : "Booking inquiry submitted successfully!" };
};

