export const updateBookingStatus = async (bookingId, newStatus) => {
  inMemoryStudentBookings = inMemoryStudentBookings.map(b => b.booking_id === bookingId ? { ...b, status: newStatus } : b);
  inMemoryOwnerBookings = inMemoryOwnerBookings.map(b => b.booking_id === bookingId ? { ...b, status: newStatus } : b);
  return { success: true, newStatus };
};

