export const updateUserStatus = async (username, action) => {
  if (action === 'delete') {
    inMemoryUsers = inMemoryUsers.filter(u => u.username !== username && u.userId !== username);
  } else if (action === 'suspend') {
    inMemoryUsers = inMemoryUsers.map(u => (u.username === username || u.userId === username) ? { ...u, status: 'DISABLED' } : u);
  } else if (action === 'activate') {
    inMemoryUsers = inMemoryUsers.map(u => (u.username === username || u.userId === username) ? { ...u, status: 'CONFIRMED' } : u);
  }
  return { success: true, username, action };
};

