// ==========================================
// REVIEWS & RATINGS API
// ==========================================
export const reviewService = {
  getReviewsForItem: async (itemId) => {
    const list = inMemoryReviews[itemId] || inMemoryReviews.d1 || [];
    const normalizedReviews = list.map(r => ({
      ...r,
      text: r.comment || r.text || "Great accommodation and service!",
      helpful_count: r.helpful_count || 0,
      not_helpful_count: r.not_helpful_count || 0,
      rating: Number(r.rating) || 5,
      created_at: r.created_at || new Date().toISOString()
    }));
    const total = normalizedReviews.length;
    const avg = total > 0 ? (normalizedReviews.reduce((acc, r) => acc + r.rating, 0) / total).toFixed(1) : 4.8;
    return {
      reviews: normalizedReviews,
      summary: {
        total_reviews: total,
        average_rating: avg,
        rating_distribution: { "5": total, "4": 0, "3": 0, "2": 0, "1": 0 },
        criteria_averages: { cleanliness: 4.8, value: 4.7, location: 4.9, amenities: 4.6 }
      },
      pagination: { hasMore: false, lastEvaluatedKey: null }
    };
  },

  createReview: async (reviewData) => {
    const newRev = {
      review_id: `rev-${Date.now()}`,
      ...reviewData,
      author_name: "Demo Student",
      created_at: new Date().toISOString(),
      helpful_count: 0
    };
    if (!inMemoryReviews[reviewData.itemId]) {
      inMemoryReviews[reviewData.itemId] = [];
    }
    inMemoryReviews[reviewData.itemId].unshift(newRev);
    return newRev;
  },

  updateReview: async (reviewId, reviewData) => {
    return { success: true, reviewId, reviewData };
  },

  deleteReview: async (reviewId) => {
    return { success: true, reviewId };
  },

  markReviewHelpful: async (reviewId, isHelpful) => {
    return { success: true, reviewId, isHelpful };
  }
};
